import React from 'react';

import X from '@pohodnik/icons/svg/Signs/X';

import { showRecipeModal } from '@apps/Recipes/components/RecipeOne/recipeOneHelper';
import { selectSeveralRecipesAsync } from '@apps/Recipes/components/RecipeSelect/recipeSelectHelper';
import PageLoader from '@components/PageLoader';
import notificationHelper, { err } from '@helpers/notificationHelper';
import PohAva from '@ui-kit/Ava';
import PohBadge, { BadgeVariant } from '@ui-kit/Badge/Badge';
import Breadcrumb from '@ui-kit/Breadcrumb';
import Button, { ButtonSize, ButtonVariant } from '@ui-kit/Button';
import Empty from '@ui-kit/Empty';
import PohList from '@ui-kit/List';
import Tabs from '@ui-kit/Tabs';

import { getRecipeCategories } from '../../../../Recipes/@services/recipes.service';
import { IRecipeCategory } from '../../../../Recipes/@types/recipes.types';
import { getHikingDataAsync } from '../../../@services/hiking.service';
import {
  addHikingRecipes,
  getHikingRecipes,
  removeRecipeFromHiking,
} from '../../../@services/hikingRecipes.service';
import { IHikingRecipe } from '../../../@types/hiking.baseTypes';
import { IHikingData } from '../../../@types/hiking.types';

interface IHikingMenuDishesProps {
  id_hiking: number;
}

const HikingMenuDishes: React.FC<IHikingMenuDishesProps> = ({ id_hiking }) => {
  const [hikingData, setHikingData] = React.useState<IHikingData | null>(null);
  const [categories, setCategories] = React.useState<IRecipeCategory[]>([]);
  const [isLoading, setIsLoading] = React.useState(true);

  const [categoryDishes, setCategoryDishes] = React.useState<Record<number, IHikingRecipe[]>>({});

  React.useEffect(() => {
    const init = async () => {
      try {
        const hd = await getHikingDataAsync(id_hiking);
        setHikingData(hd);

        const cd = await getRecipeCategories();
        setCategories(cd);

        const recipes = await getHikingRecipes(id_hiking);

        setCategoryDishes(
          recipes.reduce<Record<number, IHikingRecipe[]>>((acc, rec) => {
            if (!acc[rec.category.id]) {
              acc[rec.category.id] = [];
            }
            acc[rec.category.id].push(rec);
            return acc;
          }, {}),
        );
      } finally {
        setIsLoading(false);
      }
    };

    init().catch(err);
  }, [id_hiking]);

  const handleAdd = async (id_cat: number) => {
    const alreadyRecipeIds = (categoryDishes[id_cat] || [])?.map((x) => x.recipe.id);

    const selectedRecipes = await selectSeveralRecipesAsync({
      id_category: id_cat,
      exclude_ids: alreadyRecipeIds,
    });
    const insertedIds = await addHikingRecipes(
      id_hiking,
      selectedRecipes.map((r) => r.id),
    );
    setCategoryDishes((cur) => {
      const res = {
        ...cur,
        [id_cat]: (cur[id_cat] || []).concat(
          ...selectedRecipes.map((r, i) => {
            return {
              id: insertedIds[i],
              recipe: r,
              category: categories.find((c) => c.id === id_cat),
            } as IHikingRecipe;
          }),
        ),
      };

      return res;
    });

    notificationHelper.success(`Добавлено: ${insertedIds.length}`);
  };

  const handleRemove = async (id_recipe: number, id_category: number) => {
    await removeRecipeFromHiking(id_hiking, id_recipe);
    setCategoryDishes((cur) => ({
      ...cur,
      [id_category]: cur[id_category].filter((c) => c.recipe.id !== id_recipe),
    }));
    notificationHelper.success(`Удалено`);
  };

  if (hikingData == null || isLoading) {
    return <PageLoader />;
  }

  const renderTabs = () => {
    return categories.map((cat) => {
      const catDishes = [...(categoryDishes[cat.id] || [])];
      return {
        key: cat.id,
        title: (
          <>
            {cat.name}{' '}
            {catDishes?.length > 0 && (
              <PohBadge variant={BadgeVariant.Primary}>{catDishes.length}</PohBadge>
            )}
          </>
        ),
        content: (
          <div className="p-2">
            {catDishes?.length > 0 && (
              <PohList
                data={catDishes.map((x) => {
                  const content = (
                    <div className="d-flex align-items-center my-n1 mx-n1">
                      <PohAva src={x.recipe.photo} alt={x.recipe.name} className="me-2" />
                      <strong title={x.recipe.promo} onClick={() => showRecipeModal(x.recipe.id)}>
                        {x.recipe.name}
                      </strong>
                      <Button
                        size={ButtonSize.Small}
                        className="ms-auto"
                        variant={ButtonVariant.Light}
                        onClick={() => handleRemove(x.recipe.id, x.category.id)}
                        icon={true}
                      >
                        <X />
                      </Button>
                    </div>
                  );

                  return {
                    key: x.id,
                    content,
                  };
                })}
              />
            )}
            {!catDishes?.length && (
              <Empty>Нет блюд добавленных в категорию&nbsp;«{cat.name}»</Empty>
            )}
            <Button className="mt-3" onClick={() => handleAdd(cat.id)}>
              Добавить ({cat.name})
            </Button>
          </div>
        ),
      };
    });
  };

  return (
    <div>
      <Breadcrumb
        data={[
          { href: '/hiking', text: 'Походы' },
          { href: `/hiking/${id_hiking}`, text: hikingData.name },
          { href: `/hiking/${id_hiking}/menu`, text: 'Меню' },
          { href: `/hiking/${id_hiking}/menu/dishes`, text: 'Доступные блюда', active: true },
        ]}
      />
      <h3 className="mb-3">Доступные блюда</h3>
      <p>Добавьте сюда только те блюда, которые оптимальны для похода «{hikingData.name}».</p>
      <Tabs useHash tabs={renderTabs()} />
    </div>
  );
};

export default HikingMenuDishes;
